const reduced = () =>
  typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

function useReveal() {
  const ref = useRef(null);
  const [on, setOn] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (reduced()) { setOn(true); return; }
    const io = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setOn(true); io.disconnect(); } },
      { threshold: 0.15 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return [ref, on];
}

function Reveal({ children, delay = 0, className = "" }) {
  const [ref, on] = useReveal();
  return (
    <div ref={ref} className={`rv ${on ? "in" : ""} ${className}`} style={{ transitionDelay: `${delay}ms` }}>
      {children}
    </div>
  );
}

function Count({ to, suffix = "" }) {
  const [ref, on] = useReveal();
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!on) return;
    if (reduced()) { setN(to); return; }
    let raf, start;
    const tick = (t) => {
      if (!start) start = t;
      const p = Math.min((t - start) / 1200, 1);
      setN(Math.round(to * (1 - Math.pow(1 - p, 3))));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [on, to]);
  return <span ref={ref}>{n}{suffix}</span>;
}

function Clock() {
  const [time, setTime] = useState("");
  useEffect(() => {
    const fmt = () => {
      try {
        setTime(new Intl.DateTimeFormat("en-GB", { timeZone: "Africa/Mogadishu", hour: "2-digit", minute: "2-digit" }).format(new Date()));
      } catch (e) { setTime(""); }
    };
    fmt();
    const id = setInterval(fmt, 15000);
    return () => clearInterval(id);
  }, []);
  return time ? <span className="clock">{time}</span> : null;
}

function Particles() {
  const ref = useRef(null);
  useEffect(() => {
    if (reduced()) return;
    const c = ref.current;
    const ctx = c.getContext("2d");
    let w, h, raf;
    const mouse = { x: -999, y: -999 };
    const pts = [];
    const size = () => {
      w = c.width = c.offsetWidth * devicePixelRatio;
      h = c.height = c.offsetHeight * devicePixelRatio;
    };
    size();
    const N = Math.min(70, Math.floor(c.offsetWidth / 18));
    for (let k = 0; k < N; k++)
      pts.push({ x: Math.random() * w, y: Math.random() * h, vx: (Math.random() - 0.5) * 0.4, vy: (Math.random() - 0.5) * 0.4 });
    const move = (e) => {
      const r = c.getBoundingClientRect();
      mouse.x = (e.clientX - r.left) * devicePixelRatio;
      mouse.y = (e.clientY - r.top) * devicePixelRatio;
    };
    window.addEventListener("mousemove", move);
    window.addEventListener("resize", size);
    const D = 130 * devicePixelRatio;
    const draw = () => {
      ctx.clearRect(0, 0, w, h);
      for (const p of pts) {
        p.x += p.vx; p.y += p.vy;
        if (p.x < 0 || p.x > w) p.vx *= -1;
        if (p.y < 0 || p.y > h) p.vy *= -1;
        const dx = p.x - mouse.x, dy = p.y - mouse.y, d = Math.hypot(dx, dy);
        if (d < 120 * devicePixelRatio && d > 0) { p.x += dx / d * 1.2; p.y += dy / d * 1.2; }
        ctx.fillStyle = "rgba(232,38,26,.65)";
        ctx.beginPath(); ctx.arc(p.x, p.y, 1.6 * devicePixelRatio, 0, 7); ctx.fill();
      }
      for (let a = 0; a < pts.length; a++)
        for (let b = a + 1; b < pts.length; b++) {
          const d = Math.hypot(pts[a].x - pts[b].x, pts[a].y - pts[b].y);
          if (d < D) {
            ctx.strokeStyle = `rgba(232,38,26,${(1 - d / D) * 0.2})`;
            ctx.lineWidth = devicePixelRatio;
            ctx.beginPath(); ctx.moveTo(pts[a].x, pts[a].y); ctx.lineTo(pts[b].x, pts[b].y); ctx.stroke();
          }
        }
      raf = requestAnimationFrame(draw);
    };
    draw();
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("mousemove", move);
      window.removeEventListener("resize", size);
    };
  }, []);
  return <canvas ref={ref} className="particles" aria-hidden="true" />;
}

/* Full-person Spiderman interactive showcase - Preserves background and reveals whole person */
function SpiderPhoto() {
  const [mode, setMode] = useState("hover"); // "hover", "slider", "spiderman"
  const [sliderPos, setSliderPos] = useState(50);
  const [isHovered, setIsHovered] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const containerRef = useRef(null);

  const updatePos = (clientX) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
      setSliderPos((x / rect.width) * 100);
    }
  };

  const handlePointerDown = (e) => {
    if (mode === "slider") {
      setIsDragging(true);
      updatePos(e.clientX);
    }
  };

  const handlePointerMove = (e) => {
    if (mode === "slider" && (isDragging || e.buttons === 1)) {
      updatePos(e.clientX);
    }
  };

  const handlePointerUp = () => {
    setIsDragging(false);
  };

  return (
    <div className="spider-container">
      <div className="spider-toolbar">
        <span className="spider-tag">
          <Sparkles size={14} /> Full Suit Reveal
        </span>
        <div className="spider-mode-buttons" role="group" aria-label="Spiderman view mode">
          <button
            type="button"
            className={mode === "hover" ? "active" : ""}
            onClick={() => setMode("hover")}
            title="Hover to reveal entire Spiderman suit"
          >
            Hover Reveal
          </button>
          <button
            type="button"
            className={mode === "slider" ? "active" : ""}
            onClick={() => setMode("slider")}
            title="Drag slider across full person"
          >
            Split Slider
          </button>
          <button
            type="button"
            className={mode === "spiderman" ? "active" : ""}
            onClick={() => setMode("spiderman")}
            title="Always show Spider-Man suit"
          >
            Full Spider-Man 🕷️
          </button>
        </div>
      </div>

      <div
        ref={containerRef}
        className={`spider-card ${isHovered ? "hovered" : ""} mode-${mode}`}
        onPointerEnter={() => setIsHovered(true)}
        onPointerLeave={() => { setIsHovered(false); setIsDragging(false); }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
      >
        {/* Base Photo: Full color, background completely intact, no clipping */}
        <img
          className="spider-img spider-base"
          src={PHOTO}
          alt="Zupeir Updi - Real Photo"
          draggable="false"
        />

        {/* Top Photo: Entire person in Spiderman Suit */}
        <div
          className="spider-suit-wrapper"
          style={{
            opacity: mode === "spiderman" ? 1 : mode === "hover" ? (isHovered ? 1 : 0) : 1,
            clipPath: mode === "slider" ? `polygon(${sliderPos}% 0, 100% 0, 100% 100%, ${sliderPos}% 100%)` : "none",
            transition: mode === "slider" ? "none" : "opacity 0.4s ease-in-out",
          }}
        >
          <img
            className="spider-img spider-suit"
            src={SUIT}
            alt="Zupeir Updi - Full Spiderman Suit"
            draggable="false"
          />
        </div>

        {/* Slider Divider Line */}
        {mode === "slider" && (
          <div className="slider-handle" style={{ left: `${sliderPos}%` }}>
            <div className="slider-line" />
            <div className="slider-button">
              <Sliders size={16} />
            </div>
          </div>
        )}

        <div className="spider-badge">
          {mode === "spiderman"
            ? "🕷️ Spider-Man Suit (Full Person)"
            : mode === "slider"
            ? "Drag to compare Original ↔ Full Suit"
            : isHovered
            ? "🕷️ Spider-Man Suit Revealed!"
            : "Hover to reveal full Spider-Man suit"}
        </div>
      </div>
    </div>
  );
}

