function getRepoLiveUrl(repoName, repoHomepage) {
  if (repoHomepage && repoHomepage.startsWith("http")) return repoHomepage;
  const lower = (repoName || "").toLowerCase();
  if (
    lower === "happy-new-year" ||
    lower === "zupeir" ||
    lower === "only-js" ||
    lower === "js-project" ||
    lower.includes("portfolio") ||
    lower.includes("frontend") ||
    lower.includes("web")
  ) {
    return `https://${USER}.github.io/${repoName}/`;
  }
  return null;
}

