function Card({ r, i, onSelectPreview }) {
  const liveUrl = r.liveUrl || getRepoLiveUrl(r.name, r.homepage);
  const cardRef = useRef(null);

  const onMove = (e) => {
    const el = cardRef.current;
    if (!el) return;
    const b = el.getBoundingClientRect();
    const x = e.clientX - b.left;
    const y = e.clientY - b.top;
    el.style.setProperty("--mx", `${x}px`);
    el.style.setProperty("--my", `${y}px`);

    // 3D holographic tilt calculation
    const centerX = b.width / 2;
    const centerY = b.height / 2;
    const rotX = ((y - centerY) / centerY) * -10;
    const rotY = ((x - centerX) / centerX) * 10;
    el.style.transform = `perspective(800px) rotateX(${rotX}deg) rotateY(${rotY}deg) translateY(-6px)`;
  };

  const onLeave = () => {
    const el = cardRef.current;
    if (!el) return;
    el.style.transform = "perspective(800px) rotateX(0deg) rotateY(0deg) translateY(0)";
  };

  const col = LANG_COLOR[r.language] || "#8c9096";

  return (
    <Reveal delay={(i % 3) * 90}>
      <div
        ref={cardRef}
        className="card card-3d"
        onMouseMove={onMove}
        onMouseLeave={onLeave}
      >
        {/* Project Visual Banner / Mockup Header */}
        <div className="card-banner" onClick={() => onSelectPreview(r)}>
          <div className="card-banner-screen">
            <div className="card-banner-dots">
              <span className="dot dot-r" /><span className="dot dot-y" /><span className="dot dot-g" />
              <span className="banner-url-tag">github/{USER}/{r.name}</span>
            </div>
            <div className="card-banner-graphic">
              <CodeIcon size={26} className="banner-icon" />
              <span className="banner-code-preview">{r.language || "Code"} App</span>
            </div>
          </div>
          <div className="banner-preview-overlay">
            <Play size={16} /> <span>{liveUrl ? "Run Web Output" : "Run Console Output"}</span>
          </div>
        </div>

        <div className="card-top">
          <span className="num">{String(i + 1).padStart(2, "0")}</span>
          <div className="card-top-actions">
            {liveUrl ? (
              <button
                type="button"
                className="live-run-btn"
                onClick={(e) => {
                  e.stopPropagation();
                  onSelectPreview(r);
                }}
                title="Run live output in browser"
              >
                <Play size={12} /> Run Output
              </button>
            ) : (
              <button
                type="button"
                className="live-run-btn live-run-console"
                onClick={(e) => {
                  e.stopPropagation();
                  onSelectPreview(r);
                }}
                title="Run live console output"
              >
                <Terminal size={12} /> Run Console
              </button>
            )}
            <a
              href={r.url}
              target="_blank"
              rel="noopener noreferrer"
              className="arr-link"
              title="Open repository on GitHub"
            >
              <ArrowUpRight size={20} className="arr" />
            </a>
          </div>
        </div>

        <h3>{r.name}</h3>
        <p>{r.description || "Open-source software repository on GitHub."}</p>

        <div className="card-foot">
          {r.language && (<span className="lang"><i style={{ background: col }} />{r.language}</span>)}
          {r.stars > 0 && (<span className="lang"><Star size={13} />{r.stars}</span>)}
          {liveUrl && (
            <span className="live-ready-badge" title="Live web deployment available">
              <span className="pulse-dot-sm" /> Live
            </span>
          )}
          <a
            href={r.url}
            target="_blank"
            rel="noopener noreferrer"
            className="card-gh-pill"
            title="View code on GitHub"
          >
            <Github size={13} /> Code
          </a>
        </div>
      </div>
    </Reveal>
  );
}


function InteractiveTerminal() {
  const [history, setHistory] = useState([
    { type: "sys", text: "⚡ Zupeir OS v2.4 (Mogadishu, Somalia)" },
    { type: "sys", text: "Type 'help' to see available commands or click quick chips below." },
    { type: "cmd", text: "whoami" },
    { type: "out", text: "zupeir updi — web developer, Java programmer & cybersecurity student" }
  ]);
  const [inputVal, setInputVal] = useState("");
  const bodyRef = useRef(null);
  const inputRef = useRef(null);

  useEffect(() => {
    if (bodyRef.current) {
      bodyRef.current.scrollTop = bodyRef.current.scrollHeight;
    }
  }, [history]);

  const runCmd = (raw) => {
    const cmd = raw.trim().toLowerCase();
    if (!cmd) return;

    if (cmd === "clear") {
      setHistory([]);
      setInputVal("");
      return;
    }

    let reply = "";
    if (cmd === "help") {
      reply = "COMMANDS AVAILABLE:\n• whoami    : About Zupeir Updi\n• skills    : Technical stack & proficiency\n• journey   : University & experience timeline\n• projects  : GitHub repositories overview\n• contact   : Email and phone details\n• whatsapp  : Open direct WhatsApp chat\n• spiderman : Secret Spider-Man suit easter egg\n• clear     : Clear terminal output\n• date      : Show current Mogadishu time";
    } else if (cmd === "whoami") {
      reply = "Zupeir Updi · Semester 5 Networking & Cybersecurity student at JUST (Jamhuuriya University of Science and Technology). Frontend developer & Java enthusiast.";
    } else if (cmd === "skills") {
      reply = "Languages: JavaScript (90%), HTML5 (95%), CSS3 (92%), Java (85%), Python (80%), TypeScript (78%)\nCloud & DB: Supabase (90%), Firebase (85%), MySQL (86%), Vite, Tailwind CSS\nSystems: CCNA Routing (88%), Linux (86%), Cybersecurity (82%)";
    } else if (cmd === "journey" || cmd === "education") {
      reply = "1. Jamhuuriya University (2024 - Present): S5 Networking & Cybersecurity\n2. Freelance Web Developer (2023 - Present): Responsive web apps & Supabase DB\n3. Systems & Java Explorer (2022 - Present): 18+ GitHub open-source repositories";
    } else if (cmd === "projects" || cmd === "repos") {
      reply = "18+ Repositories hosted on GitHub: zupeir, JAVA-PROJECT, Happy-New-Year, ONLY-JS, JS-PROJECT... Visit github.com/zupeirupdi";
    } else if (cmd === "contact" || cmd === "email") {
      reply = "Email: zubeyrabdiqani80@gmail.com\nWhatsApp: +252 618240507\nLocation: Mogadishu, Somalia";
    } else if (cmd === "whatsapp" || cmd === "chat") {
      reply = "🚀 Opening WhatsApp chat with Zupeir (+252 618240507)...";
      window.open("https://wa.me/252618240507", "_blank");
    } else if (cmd === "spiderman" || cmd === "spider") {
      reply = "🕷️ 'With great power comes great responsibility.' Check the interactive Spiderman suit reveal slider in the About photo above!";
    } else if (cmd === "date" || cmd === "time") {
      reply = `Mogadishu Time: ${new Date().toLocaleTimeString("en-GB", { timeZone: "Africa/Mogadishu" })} (EAT)`;
    } else if (cmd === "sudo") {
      reply = "🔒 Permission denied: Guest user authenticated. Zupeir retains root privilege.";
    } else {
      reply = `command not found: '${raw}'. Type 'help' to see recognized commands.`;
    }

    setHistory((prev) => [
      ...prev,
      { type: "cmd", text: raw },
      { type: "out", text: reply }
    ]);
    setInputVal("");
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      runCmd(inputVal);
    }
  };

  const quickChips = ["help", "skills", "journey", "whatsapp", "spiderman", "clear"];

  return (
    <div className="term interactive-term" onClick={() => inputRef.current?.focus()} aria-label="Interactive hacker terminal">
      <div className="term-bar">
        <i /><i /><i />
        <span className="term-user-badge">zupeir@portfolio: ~ (Interactive Bash)</span>
        <div className="term-chips-bar">
          {quickChips.map((c) => (
            <button
              key={c}
              type="button"
              className="term-chip-btn"
              onClick={(e) => {
                e.stopPropagation();
                runCmd(c);
              }}
            >
              ${c}
            </button>
          ))}
        </div>
      </div>
      <div className="term-body" ref={bodyRef}>
        {history.map((h, i) => (
          <div key={i} className={`tl ${h.type}`}>
            {h.type === "cmd" ? (
              <><b>$</b> {h.text}</>
            ) : h.type === "sys" ? (
              <span className="tl-sys">{h.text}</span>
            ) : (
              <span className="tl-out-text">{h.text}</span>
            )}
          </div>
        ))}
        <div className="term-input-row">
          <b>$</b>
          <input
            ref={inputRef}
            type="text"
            className="term-input"
            value={inputVal}
            onChange={(e) => setInputVal(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type command here and press Enter..."
            aria-label="Terminal command prompt"
          />
        </div>
      </div>
    </div>
  );
}

